// uploads.ts
import express from "express";
import { randomUUID } from "node:crypto";
import {
  S3Client,
  CreateMultipartUploadCommand,
  UploadPartCommand,
  AbortMultipartUploadCommand,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

const s3 = new S3Client({ region: process.env.AWS_REGION });
const BUCKET = process.env.UPLOAD_BUCKET!;

const PART_SIZE = 50 * 1024 * 1024;               // 50 MB
const MAX_FILE_SIZE = 50 * 1024 * 1024 * 1024;    // 50 GB app-level cap (adjust)
const MAX_PARTS = 10_000;                         // S3 hard limit
const URL_TTL_SECONDS = 6 * 60 * 60;              // 6h, so resumes work after a pause

const ALLOWED_TYPES = new Set(["video/mp4", "video/quicktime", "video/webm", "video/x-matroska"]);

export const uploadsRouter = express.Router();

uploadsRouter.post("/uploads", express.json(), async (req, res) => {
  const { filename, contentType, size } = req.body ?? {};

  // --- validation ---
  if (typeof filename !== "string" || !filename.trim()) {
    return res.status(400).json({ error: "filename is required" });
  }
  if (!ALLOWED_TYPES.has(contentType)) {
    return res.status(400).json({ error: "unsupported content type" });
  }
  if (!Number.isInteger(size) || size <= 0 || size > MAX_FILE_SIZE) {
    return res.status(400).json({ error: "invalid size" });
  }

  const partCount = Math.ceil(size / PART_SIZE);
  if (partCount > MAX_PARTS) {
    return res.status(400).json({ error: "file too large" });
  }

  // Server-generated key; never trust the client's filename for the path.
  // (Add your auth'd user id to the prefix if you have one.)
  const key = `videos/incoming/${randomUUID()}`;

  // --- start the multipart upload ---
  const { UploadId } = await s3.send(
    new CreateMultipartUploadCommand({
      Bucket: BUCKET,
      Key: key,
      ContentType: contentType,
      Metadata: { originalname: encodeURIComponent(filename) },
    })
  );
  if (!UploadId) return res.status(502).json({ error: "failed to start upload" });

  try {
    // --- presign one URL per part ---
    const parts = await Promise.all(
      Array.from({ length: partCount }, async (_, i) => {
        const partNumber = i + 1;
        const url = await getSignedUrl(
          s3,
          new UploadPartCommand({
            Bucket: BUCKET,
            Key: key,
            UploadId,
            PartNumber: partNumber,
          }),
          { expiresIn: URL_TTL_SECONDS }
        );
        return { partNumber, url };
      })
    );

    // TODO: persist { uploadId: UploadId, key, userId, size, partCount, status: "in_progress" }
    // so you can authorize resume/complete/abort calls and clean up abandoned uploads.

    return res.status(201).json({
      uploadId: UploadId,
      key,
      partSize: PART_SIZE,
      partCount,
      expiresInSeconds: URL_TTL_SECONDS,
      parts, // [{ partNumber, url }]
    });
  } catch (err) {
    // Don't leave an orphaned upload (and its storage costs) behind.
    await s3
      .send(new AbortMultipartUploadCommand({ Bucket: BUCKET, Key: key, UploadId }))
      .catch(() => {});
    throw err;
  }
});
```

**How the client uses it**
- Slice the file into `partSize` chunks. Part *N* covers bytes `[(N-1)*partSize, N*partSize)`, and the last part is smaller.
- `PUT` each chunk to its URL. The request must have no extra signed headers, just the body.
- Save the `ETag` response header from each `PUT`. You need the `{PartNumber, ETag}` list to complete the upload.

**Gotchas to handle**
1. **Bucket CORS:** allow `PUT` from your origin and set `ExposeHeaders: ["ETag"]`. Otherwise browsers can't read the ETag and you can't complete the upload.
2. **Abandoned uploads:** add a lifecycle rule with `AbortIncompleteMultipartUpload` (e.g. after 3 days). Incomplete parts are billed until aborted.
3. **Part size:** S3 requires every part except the last to be at least 5 MB. 50 MB is fine, and it supports files up to about 500 GB at 10,000 parts.
4. **Auth:** put this route behind your normal auth middleware, and tie `uploadId` to the user in your DB.

**Still needed for the full flow**
- `POST /uploads/:uploadId/complete` takes the parts and ETags and calls `CompleteMultipartUploadCommand`.
- `GET /uploads/:uploadId/parts` calls `ListPartsCommand`, so a resuming client knows which parts are already uploaded. It can also re-sign URLs for the remaining parts if the originals expired.
- `DELETE /uploads/:uploadId` calls `AbortMultipartUploadCommand`.

