```ts
// video-upload.ts
export interface UploadOptions {
  apiBase?: string;                 // default "/api"
  concurrency?: number;             // parallel part uploads, default 4
  maxRetries?: number;              // per part, default 5
  signal?: AbortSignal;             // pause/cancel; does NOT abort the server-side upload
  onProgress?: (p: { loaded: number; total: number }) => void;
}

interface PartUrl { partNumber: number; url: string }
interface CompletedPart { partNumber: number; etag: string }
interface Session {
  uploadId: string;
  key: string;
  partSize: number;
  partCount: number;
  parts: PartUrl[];                 // URLs still needed
}

class PartError extends Error {
  constructor(msg: string, public retryable: boolean) { super(msg); }
}

// ---------- public API ----------

export async function uploadVideo(file: File, opts: UploadOptions = {}) {
  const base = opts.apiBase ?? "/api";
  const session = await api<Session>("POST", `${base}/uploads`, {
    filename: file.name,
    contentType: file.type,
    size: file.size,
  });
  // Persist session.uploadId (e.g. localStorage) if you want resume after reload.
  return uploadParts(file, session, [], opts);
}

// Assumes GET /uploads/:id/parts returns already-uploaded parts plus fresh URLs for the rest.
export async function resumeVideoUpload(file: File, uploadId: string, opts: UploadOptions = {}) {
  const base = opts.apiBase ?? "/api";
  const r = await api<{
    key: string; partSize: number; partCount: number;
    completed: CompletedPart[]; remaining: PartUrl[];
  }>("GET", `${base}/uploads/${uploadId}/parts`);

  return uploadParts(
    file,
    { uploadId, key: r.key, partSize: r.partSize, partCount: r.partCount, parts: r.remaining },
    r.completed,
    opts
  );
}

// ---------- core ----------

async function uploadParts(
  file: File,
  s: Session,
  alreadyDone: CompletedPart[],
  opts: UploadOptions
): Promise<{ key: string }> {
  const base = opts.apiBase ?? "/api";
  const concurrency = opts.concurrency ?? 4;
  const maxRetries = opts.maxRetries ?? 5;

  const completed = new Map(alreadyDone.map((p) => [p.partNumber, p]));
  const inFlight = new Map<number, number>();   // partNumber -> bytes sent so far
  const pending = s.parts.filter((p) => !completed.has(p.partNumber));

  // Internal controller lets one failed part cancel its siblings.
  const internal = new AbortController();
  opts.signal?.addEventListener("abort", () => internal.abort(), { once: true });
  if (opts.signal?.aborted) internal.abort();

  const partLength = (n: number) =>
    Math.min(n * s.partSize, file.size) - (n - 1) * s.partSize;

  const report = () => {
    let loaded = 0;
    for (const n of completed.keys()) loaded += partLength(n);
    for (const bytes of inFlight.values()) loaded += bytes;
    opts.onProgress?.({ loaded, total: file.size });
  };
  report();

  let next = 0;
  const worker = async () => {
    while (!internal.signal.aborted) {
      const part = pending[next++];
      if (!part) return;

      const start = (part.partNumber - 1) * s.partSize;
      const blob = file.slice(start, start + partLength(part.partNumber)); // lazy, not read into memory

      const etag = await withRetry(maxRetries, internal.signal, () => {
        inFlight.set(part.partNumber, 0);   // reset on each attempt
        report();
        return putPart(part.url, blob, internal.signal, (sent) => {
          inFlight.set(part.partNumber, sent);
          report();
        });
      });

      inFlight.delete(part.partNumber);
      completed.set(part.partNumber, { partNumber: part.partNumber, etag });
      report();
    }
  };

  try {
    await Promise.all(
      Array.from({ length: Math.min(concurrency, pending.length) }, worker)
    );
  } catch (err) {
    internal.abort();   // stop sibling uploads
    throw err;          // upload stays resumable server-side
  }

  const parts = [...completed.values()].sort((a, b) => a.partNumber - b.partNumber);
  if (parts.length !== s.partCount) throw new Error("Upload incomplete");

  await api("POST", `${base}/uploads/${s.uploadId}/complete`, { parts });
  return { key: s.key };
}

// ---------- helpers ----------

function putPart(
  url: string,
  body: Blob,
  signal: AbortSignal,
  onSent: (bytes: number) => void
): Promise<string> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("PUT", url);                       // no extra headers: they'd break the signature
    xhr.upload.onprogress = (e) => onSent(e.loaded);
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        const etag = xhr.getResponseHeader("ETag");
        return etag
          ? resolve(etag)
          : reject(new PartError("No ETag: add ExposeHeaders ETag to bucket CORS", false));
      }
      // 403 usually means expired/invalid signature: retrying the same URL won't help.
      const retryable = xhr.status >= 500 || xhr.status === 429 || xhr.status === 408;
      reject(new PartError(`Part upload failed: HTTP ${xhr.status}`, retryable));
    };
    xhr.onerror = () => reject(new PartError("Network error", true));
    xhr.ontimeout = () => reject(new PartError("Timeout", true));
    xhr.onabort = () => reject(new DOMException("Aborted", "AbortError"));

    if (signal.aborted) return xhr.abort();
    signal.addEventListener("abort", () => xhr.abort(), { once: true });
    xhr.send(body);
  });
}

async function withRetry<T>(
  maxRetries: number,
  signal: AbortSignal,
  fn: () => Promise<T>
): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (err) {
      const retryable = err instanceof PartError && err.retryable;
      if (!retryable || attempt >= maxRetries || signal.aborted) throw err;
      const delay = Math.min(30_000, 500 * 2 ** attempt) * (0.5 + Math.random() / 2);
      await new Promise((r) => setTimeout(r, delay));
    }
  }
}

async function api<T = unknown>(method: string, url: string, body?: unknown): Promise<T> {
  const res = await fetch(url, {
    method,
    credentials: "include",
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) throw new Error(`${method} ${url} failed: ${res.status}`);
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}
