This is a browser-side TypeScript uploader. It uses `XMLHttpRequest` for the part PUTs because `fetch` can't report upload progress.

```ts
export interface PartInfo { partNumber: number; url: string }
export interface CompletedPart { PartNumber: number; ETag: string }

interface StartResponse {
  uploadId: string;
  key: string;
  partSize: number;
  parts: PartInfo[];
}

export interface UploadOptions {
  concurrency?: number;   // default 4
  maxRetries?: number;    // per part, default 5
  apiBase?: string;       // default ""
  signal?: AbortSignal;
  onProgress?: (p: { loaded: number; total: number; percent: number }) => void;
}

class HttpError extends Error {
  constructor(public status: number) { super(`HTTP ${status}`); }
}
class FatalUploadError extends Error {}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function isRetryable(err: unknown): boolean {
  if (err instanceof FatalUploadError) return false;
  if (err instanceof DOMException && err.name === "AbortError") return false;
  if (err instanceof HttpError) {
    return err.status === 408 || err.status === 429 || err.status >= 500;
  }
  return true; // network errors
}

function putPart(
  url: string,
  body: Blob,
  signal: AbortSignal,
  onBytes: (loaded: number) => void
): Promise<string> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) return reject(new DOMException("Aborted", "AbortError"));

    const xhr = new XMLHttpRequest();
    const onAbort = () => xhr.abort();
    signal.addEventListener("abort", onAbort, { once: true });
    const cleanup = () => signal.removeEventListener("abort", onAbort);

    xhr.open("PUT", url);
    xhr.upload.onprogress = (e) => { if (e.lengthComputable) onBytes(e.loaded); };
    xhr.onload = () => {
      cleanup();
      if (xhr.status >= 200 && xhr.status < 300) {
        const etag = xhr.getResponseHeader("ETag");
        if (!etag) {
          reject(new FatalUploadError(
            "Upload succeeded but ETag is not readable. Add ExposeHeaders: [\"ETag\"] to the bucket CORS config."
          ));
        } else {
          resolve(etag);
        }
      } else if (xhr.status === 403) {
        reject(new FatalUploadError(
          "403 from storage: the presigned URL has probably expired. Resume the upload to get fresh URLs."
        ));
      } else {
        reject(new HttpError(xhr.status));
      }
    };
    xhr.onerror = () => { cleanup(); reject(new Error("Network error")); };
    xhr.onabort = () => { cleanup(); reject(new DOMException("Aborted", "AbortError")); };
    xhr.send(body);
  });
}

/**
 * Uploads the given parts with a bounded worker pool.
 * `alreadyDone` lets a resume flow skip parts S3 already has.
 */
export async function uploadParts(
  file: File,
  partSize: number,
  parts: PartInfo[],
  opts: UploadOptions = {},
  alreadyDone: CompletedPart[] = []
): Promise<CompletedPart[]> {
  const { concurrency = 4, maxRetries = 5, onProgress } = opts;

  const sizeOf = (partNumber: number) =>
    Math.min(partNumber * partSize, file.size) - (partNumber - 1) * partSize;

  // Bytes confirmed per part (completed) or in flight (current attempt).
  const loadedByPart = new Map<number, number>();
  for (const p of alreadyDone) loadedByPart.set(p.PartNumber, sizeOf(p.PartNumber));

  const report = () => {
    if (!onProgress) return;
    let loaded = 0;
    for (const v of loadedByPart.values()) loaded += v;
    onProgress({ loaded, total: file.size, percent: (loaded / file.size) * 100 });
  };
  report();

  // Internal controller: aborts in-flight parts when one part fails fatally
  // or the caller cancels.
  const ctrl = new AbortController();
  opts.signal?.addEventListener("abort", () => ctrl.abort(), { once: true });
  if (opts.signal?.aborted) ctrl.abort();

  const completed: CompletedPart[] = [...alreadyDone];
  let next = 0;

  async function uploadOne(part: PartInfo) {
    const start = (part.partNumber - 1) * partSize;
    const blob = file.slice(start, Math.min(start + partSize, file.size));

    for (let attempt = 0; ; attempt++) {
      try {
        loadedByPart.set(part.partNumber, 0);
        const etag = await putPart(part.url, blob, ctrl.signal, (loaded) => {
          loadedByPart.set(part.partNumber, loaded);
          report();
        });
        loadedByPart.set(part.partNumber, blob.size);
        report();
        completed.push({ PartNumber: part.partNumber, ETag: etag });
        return;
      } catch (err) {
        loadedByPart.set(part.partNumber, 0); // don't count failed bytes
        report();
        if (attempt >= maxRetries || !isRetryable(err)) throw err;
        // exponential backoff with jitter, capped at 30s
        const delay = Math.min(30_000, 500 * 2 ** attempt) * (0.5 + Math.random() / 2);
        await sleep(delay);
        if (ctrl.signal.aborted) throw new DOMException("Aborted", "AbortError");
      }
    }
  }

  async function worker() {
    while (!ctrl.signal.aborted) {
      const i = next++;
      if (i >= parts.length) return;
      try {
        await uploadOne(parts[i]);
      } catch (err) {
        ctrl.abort(); // stop sibling workers and in-flight requests
        throw err;
      }
    }
  }

  const results = await Promise.allSettled(
    Array.from({ length: Math.min(concurrency, parts.length) }, worker)
  );

  // Prefer a real error over the AbortErrors it caused in sibling workers.
  const failures = results.filter((r): r is PromiseRejectedResult => r.status === "rejected");
  if (failures.length) {
    const real = failures.find(
      (f) => !(f.reason instanceof DOMException && f.reason.name === "AbortError")
    );
    throw (real ?? failures[0]).reason;
  }

  // S3 requires the parts list in ascending PartNumber order.
  return completed.sort((a, b) => a.PartNumber - b.PartNumber);
}

async function api<T>(method: string, url: string, body?: unknown): Promise<T> {
  const res = await fetch(url, {
    method,
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
    credentials: "include", // or add your Authorization header here
  });
  if (!res.ok) throw new Error(`${method} ${url} failed: ${res.status}`);
  return res.status === 204 ? (undefined as T) : res.json();
}

export async function uploadFile(file: File, opts: UploadOptions = {}) {
  const base = opts.apiBase ?? "";

  const start = await api<StartResponse>("POST", `${base}/uploads/multipart`, {
    filename: file.name,
    contentType: file.type,
    size: file.size,
  });

  // Sanity check: server and client must agree on the part layout.
  if (start.parts.length !== Math.ceil(file.size / start.partSize)) {
    throw new Error("Server returned an unexpected number of parts");
  }

  const completed = await uploadParts(file, start.partSize, start.parts, opts);

  await api("POST", `${base}/uploads/${start.uploadId}/complete`, { parts: completed });
  return { uploadId: start.uploadId, key: start.key };
}
