I don't know which provider you're using yet, so this assumes the most common scheme: an HMAC-SHA256 over a timestamp plus the raw body, sent in a header like `t=1700000000,v1=<hex signature>`. That's Stripe's format, and many providers are similar. The code is Node/Express, so tell me if you're on something else.

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.PAYMENT_WEBHOOK_SECRET;
const TOLERANCE_SECONDS = 300; // reject events older than 5 minutes

function verifySignature(rawBody, header, secret, tolerance = TOLERANCE_SECONDS) {
  if (!header || !secret) return false;

  // Parse "t=...,v1=...,v1=..." (multiple v1 values can appear during secret rotation)
  let timestamp = null;
  const signatures = [];
  for (const part of header.split(',')) {
    const [key, value] = part.split('=');
    if (key === 't') timestamp = value;
    else if (key === 'v1') signatures.push(value);
  }
  if (!timestamp || signatures.length === 0) return false;

  // Replay protection
  const age = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (!Number.isFinite(age) || age > tolerance) return false;

  // Sign "<timestamp>.<raw body>"
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.`)
    .update(rawBody)
    .digest();

  // Constant-time comparison against each provided signature
  return signatures.some((sig) => {
    const provided = Buffer.from(sig, 'hex');
    return provided.length === expected.length &&
           crypto.timingSafeEqual(provided, expected);
  });
}

const app = express();

// Raw body is required: the signature covers the exact bytes sent.
// Use express.raw on this route only, NOT express.json.
app.post(
  '/webhooks/refunds',
  express.raw({ type: 'application/json' }),
  (req, res) => {
    const header = req.get('Signature-Header-Name'); // replace with your provider's header

    if (!verifySignature(req.body, header, WEBHOOK_SECRET)) {
      return res.status(400).send('invalid signature');
    }

    const event = JSON.parse(req.body.toString('utf8'));

    // ...handle the event (upsert into refunds), then acknowledge quickly
    res.sendStatus(200);
  }
);
```

Key points:

- **Use the raw body.** If a JSON parser runs first and you re-serialize, the bytes change and the signature won't match. This is the most common cause of "signature always fails" bugs.
- **Constant-time compare.** `timingSafeEqual` avoids leaking information through comparison timing. It throws on mismatched lengths, hence the length check.
- **Timestamp tolerance.** Without it, someone who captures a valid request can replay it indefinitely. Your `ON CONFLICT` upsert limits the damage, but you should still reject stale events.
- **Verify before doing anything else.** No parsing, DB access, or logging of the payload contents until the signature passes.
- **Secret handling.** Keep it in an environment variable or secrets manager, and use the per-endpoint signing secret from the provider's dashboard (usually different from your API key).
- **Fail closed.** A missing header or missing secret returns a rejection, never a pass-through.

If your provider has an official SDK helper, prefer it over hand-rolled code. Stripe's `stripe.webhooks.constructEvent(rawBody, header, secret)` does all of this. If your provider uses a different scheme (for example, signing only the body, base64-encoded signatures, or a different header), the structure stays the same but the parsing and signed string change.

