The retry unit is the whole chunk (read, then upload), and `last_id` only advances after the upload succeeds. A failed chunk is therefore re-read from the same starting point and written to the same object key, so a retry overwrites any partial attempt instead of duplicating data.

```python
import csv, gzip, io, random, time
import boto3, psycopg
from botocore.exceptions import BotoCoreError, ClientError
from psycopg import sql

s3 = boto3.client("s3")
CHUNK = 50_000

def is_transient(exc):
    if isinstance(exc, (psycopg.OperationalError, psycopg.InterfaceError, BotoCoreError)):
        return True
    if isinstance(exc, ClientError):
        status = exc.response["ResponseMetadata"]["HTTPStatusCode"]
        code = exc.response["Error"]["Code"]
        return status >= 500 or code in {"SlowDown", "Throttling", "RequestTimeout"}
    return False

def with_retry(fn, attempts=5, base=1.0, cap=60.0):
    for n in range(1, attempts + 1):
        try:
            return fn()
        except Exception as exc:
            if not is_transient(exc) or n == attempts:
                raise  # permanent error or out of attempts: fail the job loudly
            delay = random.uniform(0, min(cap, base * 2 ** n))  # full jitter
            print(f"attempt {n} failed ({exc!r}); retrying in {delay:.1f}s")
            time.sleep(delay)

def fetch_chunk(dsn, table, last_id):
    t = sql.Identifier(table)
    with psycopg.connect(dsn) as conn, conn.cursor() as cur:  # fresh connection per attempt
        if last_id is None:
            cur.execute(sql.SQL("SELECT * FROM {} ORDER BY id LIMIT %s").format(t), (CHUNK,))
        else:
            cur.execute(sql.SQL("SELECT * FROM {} WHERE id > %s ORDER BY id LIMIT %s").format(t),
                        (last_id, CHUNK))
        cols = [d.name for d in cur.description]
        return cols, cur.fetchall()

def upload_chunk(bucket, key, cols, rows):
    buf = io.BytesIO()  # in memory, never touches local disk
    with gzip.GzipFile(fileobj=buf, mode="wb") as gz:
        w = csv.writer(io.TextIOWrapper(gz, encoding="utf-8", write_through=True))
        w.writerow(cols)
        w.writerows(rows)
    buf.seek(0)
    s3.upload_fileobj(buf, bucket, key)

def sync_table(dsn, table, bucket, run_id, last_id=None):
    while True:
        def attempt():
            cols, rows = fetch_chunk(dsn, table, last_id)
            if not rows:
                return None
            # Key is derived from the chunk's starting point, so a retry overwrites the same object
            key = f"{table}/{run_id}/after-{last_id if last_id is not None else 'start'}.csv.gz"
            upload_chunk(bucket, key, cols, rows)
            return rows[-1][cols.index("id")], len(rows)

        result = with_retry(attempt)
        if result is None:
            break
        last_id, n = result
        # Optionally persist last_id here (DB row, S3 object) to resume after a crash
        if n < CHUNK:
            break
```

- **Idempotent keys:** the key depends on `run_id` and the chunk's starting `last_id`, not on a counter or timestamp. S3 PUTs are atomic overwrites, so retries never leave half-written or duplicate objects. Keep `run_id` stable if you restart the same weekly run, so the restart overwrites rather than duplicates.
- **Read and upload retry together:** if the upload fails, the rows in memory are discarded and re-read. That costs one extra query but avoids holding state across a possibly dead connection.
- **Only transient errors are retried:** connection drops, throttling, and 5xx responses get backoff. Bugs, bad SQL, and permission errors fail immediately so they don't burn five attempts.
- **Jittered backoff:** this stops parallel table workers from retrying in lockstep against a struggling source or S3.
- **Exhausted retries raise:** the job fails with the last good `last_id` known, rather than silently skipping a chunk. Persist that value if you want to resume mid-table instead of restarting the table.
- **Memory:** each chunk is held in RAM, so 50,000 rows of wide or blob-heavy data can be large. Lower `CHUNK` if memory gets tight.
- **Non-integer or composite keys:** adjust the `WHERE` and the `last_id` tracking to match.

