## `scripts/upload-to-cdn.mjs`

```js
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import {
  S3Client,
  PutObjectCommand,
  HeadObjectCommand,
} from "@aws-sdk/client-s3";
import mime from "mime-types";

const {
  CDN_BUCKET,
  CDN_PREFIX = "quote-page",
  AWS_REGION = "us-east-1",
  ASSET_DIR = "dist",
  DRY_RUN,
} = process.env;

if (!CDN_BUCKET) {
  console.error("CDN_BUCKET is required");
  process.exit(1);
}

const s3 = new S3Client({ region: AWS_REGION });

// Only upload what the browser fetches as static assets.
// HTML stays on your origin; source maps stay private.
const SKIP = [/\.html?$/i, /\.map$/i];

// Matches fingerprints like app.3f9a1c2b.js or logo-3f9a1c2b.png
const isHashed = (file) => /[.-][0-9a-f]{8,}\.[a-z0-9]+$/i.test(file);

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else yield full;
  }
}

async function exists(Key) {
  try {
    await s3.send(new HeadObjectCommand({ Bucket: CDN_BUCKET, Key }));
    return true;
  } catch (err) {
    if (err.name === "NotFound" || err.$metadata?.httpStatusCode === 404) {
      return false;
    }
    throw err;
  }
}

async function upload(file) {
  const rel = path.relative(ASSET_DIR, file).split(path.sep).join("/");
  const Key = `${CDN_PREFIX}/${rel}`;
  const hashed = isHashed(rel);

  // Hashed files are immutable: skip if already there.
  if (hashed && (await exists(Key))) {
    return { Key, status: "skipped" };
  }

  if (DRY_RUN) return { Key, status: "dry-run" };

  await s3.send(
    new PutObjectCommand({
      Bucket: CDN_BUCKET,
      Key,
      Body: await readFile(file),
      ContentType: mime.lookup(file) || "application/octet-stream",
      CacheControl: hashed
        ? "public, max-age=31536000, immutable"
        : "public, max-age=300",
    })
  );
  return { Key, status: "uploaded" };
}

async function main() {
  const files = [];
  for await (const f of walk(ASSET_DIR)) {
    if (!SKIP.some((re) => re.test(f))) files.push(f);
  }

  // Simple concurrency pool
  const CONCURRENCY = 10;
  const results = [];
  let i = 0;
  await Promise.all(
    Array.from({ length: CONCURRENCY }, async () => {
      while (i < files.length) {
        const file = files[i++];
        const r = await upload(file);
        results.push(r);
        console.log(`${r.status.padEnd(9)} ${r.Key}`);
      }
    })
  );

  const count = (s) => results.filter((r) => r.status === s).length;
  console.log(
    `\nDone: ${count("uploaded")} uploaded, ${count("skipped")} skipped, ${count("dry-run")} dry-run`
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

