I don't know your stack, so this assumes Node, a `dist/` build output, and S3 behind CloudFront. Adjust for your provider.

```js
// scripts/upload-assets.mjs
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { CloudFrontClient, CreateInvalidationCommand } from "@aws-sdk/client-cloudfront";
import { readdir, readFile } from "node:fs/promises";
import { join, extname, relative, sep } from "node:path";
import mime from "mime-types";

const {
  CDN_BUCKET,
  CDN_PREFIX = "assets",
  CLOUDFRONT_DISTRIBUTION_ID,
  AWS_REGION = "us-east-1",
} = process.env;

if (!CDN_BUCKET) throw new Error("CDN_BUCKET is required");

const DIST_DIR = "dist";
const s3 = new S3Client({ region: AWS_REGION });

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else yield full;
  }
}

// Hashed filenames like app.3f9a1c2b.js can be cached forever
const isHashed = (file) => /\.[0-9a-f]{8,}\./.test(file);

async function upload(file) {
  const key = [CDN_PREFIX, relative(DIST_DIR, file).split(sep).join("/")].join("/");
  const body = await readFile(file);
  const ext = extname(file);

  await s3.send(
    new PutObjectCommand({
      Bucket: CDN_BUCKET,
      Key: key,
      Body: body,
      ContentType: mime.lookup(ext) || "application/octet-stream",
      CacheControl: isHashed(file)
        ? "public, max-age=31536000, immutable"
        : "public, max-age=300",
    })
  );
  console.log("uploaded", key);
}

async function main() {
  const files = [];
  for await (const f of walk(DIST_DIR)) {
    if (!f.endsWith(".map") && !f.endsWith(".html")) files.push(f);
  }

  // Upload with limited concurrency
  const concurrency = 10;
  let i = 0;
  await Promise.all(
    Array.from({ length: concurrency }, async () => {
      while (i < files.length) await upload(files[i++]);
    })
  );

  if (CLOUDFRONT_DISTRIBUTION_ID) {
    await new CloudFrontClient({ region: AWS_REGION }).send(
      new CreateInvalidationCommand({
        DistributionId: CLOUDFRONT_DISTRIBUTION_ID,
        InvalidationBatch: {
          CallerReference: String(Date.now()),
          Paths: { Quantity: 1, Items: [`/${CDN_PREFIX}/*`] },
        },
      })
    );
    console.log("invalidation created");
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

