## Design decisions (driven by "nothing can be lost")

- **Save on every change** (debounced, plus a flush when the app is backgrounded), not on a Save button.
- **Each save is a single transaction**, and we only report success after the transaction commits, not when the request is queued.
- **Nothing is deleted until the server has confirmed it**, and sync is tracked per revision. If an inspector edits a form while it's uploading, it stays marked as unsynced.
- **IDs are generated on the device** (UUIDs), so the server can deduplicate retried uploads.
- **Photos are stored as Blobs** in a separate store, linked to the form.
- **We ask the browser for persistent storage**, because otherwise it may evict the data under storage pressure. Safari can also purge data for sites that haven't been used in a while.

## `formStore.ts`

```ts
import { openDB, DBSchema, IDBPDatabase } from 'idb'; // npm i idb (v8+)

export interface FormRecord {
  id: string;                       // client-generated UUID, also the idempotency key for sync
  formType: string;
  schemaVersion: number;            // version of the form definition used
  data: Record<string, unknown>;
  completed: boolean;
  createdAt: number;
  updatedAt: number;
  revision: number;                 // incremented on every local save
  syncedRevision: number;           // highest revision the server has confirmed (0 = never)
  dirty: 0 | 1;                     // 1 if revision > syncedRevision (indexable)
}

export interface AttachmentRecord {
  id: string;
  formId: string;
  blob: Blob;
  mimeType: string;
  createdAt: number;
  synced: 0 | 1;
}

interface InspectionDB extends DBSchema {
  forms: {
    key: string;
    value: FormRecord;
    indexes: { byDirty: number; byUpdatedAt: number };
  };
  attachments: {
    key: string;
    value: AttachmentRecord;
    indexes: { byForm: string; bySynced: number };
  };
}

let dbPromise: Promise<IDBPDatabase<InspectionDB>> | null = null;

function getDB() {
  dbPromise ??= openDB<InspectionDB>('inspections', 1, {
    upgrade(db) {
      const forms = db.createObjectStore('forms', { keyPath: 'id' });
      forms.createIndex('byDirty', 'dirty');
      forms.createIndex('byUpdatedAt', 'updatedAt');

      const att = db.createObjectStore('attachments', { keyPath: 'id' });
      att.createIndex('byForm', 'formId');
      att.createIndex('bySynced', 'synced');
    },
  });
  return dbPromise;
}

/** Call once at startup. Returns false if the browser refused; warn the user/admin if so. */
export async function requestPersistentStorage(): Promise<boolean> {
  if (!navigator.storage?.persist) return false;
  return (await navigator.storage.persisted()) || (await navigator.storage.persist());
}

// Strict durability: the transaction isn't "complete" until flushed to disk.
const RW = { durability: 'strict' } as const;

export async function createForm(formType: string, schemaVersion: number,
                                 initialData: Record<string, unknown> = {}): Promise<FormRecord> {
  const db = await getDB();
  const now = Date.now();
  const record: FormRecord = {
    id: crypto.randomUUID(),
    formType, schemaVersion,
    data: initialData,
    completed: false,
    createdAt: now, updatedAt: now,
    revision: 1, syncedRevision: 0, dirty: 1,
  };
  const tx = db.transaction('forms', 'readwrite', RW);
  tx.store.add(record);
  await tx.done;                      // resolves only after commit
  return record;
}

export async function getForm(id: string) {
  return (await getDB()).get('forms', id);
}

/** Merge a patch of fields into the form. Read-modify-write is atomic within one transaction. */
export async function saveForm(id: string, patch: Record<string, unknown>,
                               opts: { completed?: boolean } = {}): Promise<FormRecord> {
  const db = await getDB();
  const tx = db.transaction('forms', 'readwrite', RW);
  const existing = await tx.store.get(id);
  if (!existing) { tx.abort(); throw new Error(`Form ${id} not found`); }

  const updated: FormRecord = {
    ...existing,
    data: { ...existing.data, ...patch },
    completed: opts.completed ?? existing.completed,
    updatedAt: Date.now(),
    revision: existing.revision + 1,
    dirty: 1,
  };
  await tx.store.put(updated);
  await tx.done;
  return updated;
}

export async function addAttachment(formId: string, blob: Blob): Promise<string> {
  const db = await getDB();
  const rec: AttachmentRecord = {
    id: crypto.randomUUID(), formId, blob,
    mimeType: blob.type, createdAt: Date.now(), synced: 0,
  };
  const tx = db.transaction(['attachments', 'forms'], 'readwrite', RW);
  const form = await tx.objectStore('forms').get(formId);
  if (!form) { tx.abort(); throw new Error(`Form ${formId} not found`); }
  await tx.objectStore('attachments').add(rec);
  // Touch the form so it's flagged for sync too.
  await tx.objectStore('forms').put({
    ...form, updatedAt: Date.now(), revision: form.revision + 1, dirty: 1,
  });
  await tx.done;
  return rec.id;
}

export async function getAttachments(formId: string) {
  return (await getDB()).getAllFromIndex('attachments', 'byForm', formId);
}

// ---- Hooks for the sync layer (to be written next) ----

export async function listUnsynced(): Promise<FormRecord[]> {
  return (await getDB()).getAllFromIndex('forms', 'byDirty', 1);
}

/** Call after the server confirms it stored `revisionSent`. Edits made during upload stay dirty. */
export async function markSynced(id: string, revisionSent: number) {
  const db = await getDB();
  const tx = db.transaction('forms', 'readwrite', RW);
  const rec = await tx.store.get(id);
  if (rec) {
    const syncedRevision = Math.max(rec.syncedRevision, revisionSent);
    await tx.store.put({ ...rec, syncedRevision, dirty: rec.revision > syncedRevision ? 1 : 0 });
  }
  await tx.done;
}

export async function markAttachmentSynced(id: string) {
  const db = await getDB();
  const tx = db.transaction('attachments', 'readwrite', RW);
  const rec = await tx.store.get(id);
  if (rec) await tx.store.put({ ...rec, synced: 1 });
  await tx.done;
}
```

## Autosave helper

```ts
import { saveForm } from './formStore';

export function createAutosaver(formId: string, delayMs = 500) {
  let pending: Record<string, unknown> = {};
  let timer: number | undefined;
  let inFlight: Promise<unknown> = Promise.resolve();

  function flush(): Promise<unknown> {
    clearTimeout(timer);
    if (Object.keys(pending).length === 0) return inFlight;
    const patch = pending;
    pending = {};
    // Chain saves so they commit in order.
    inFlight = inFlight.then(() => saveForm(formId, patch));
    return inFlight;
  }

  function update(fields: Record<string, unknown>) {
    pending = { ...pending, ...fields };
    clearTimeout(timer);
    timer = window.setTimeout(flush, delayMs);
  }

  // Flush when the app is backgrounded or closed.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') flush();
  });
  window.addEventListener('pagehide', flush);

  return { update, flush };
}
```

Wire each input's `onChange` to `autosaver.update({ fieldName: value })`. Also `await autosaver.flush()` before navigating away or when the inspector taps "Complete".

## Caveats

- **The tablet is a single point of failure.** If it's dropped, stolen, or wiped before sync, the data is gone. You can reduce the risk by syncing eagerly whenever any connection appears and by showing inspectors a clear "unsynced forms" indicator. Make sure they don't leave a site with unsynced work if they can avoid it.
- **Install the PWA to the home screen** on iPadOS. Safari is much more aggressive about evicting data for ordinary browser tabs.
- **Don't delete synced forms immediately.** Keep them for a retention period (for example, 30 days) so a server-side problem doesn't leave you with no copy.
- **Schema changes:** `schemaVersion` on each record lets you migrate old drafts when the form definition changes.

