**Schema**

```sql
create table field_events (
  id                bigserial primary key,
  form_id           uuid        not null,
  field_id          text        not null,
  device_id         text        not null,
  seq               bigint      not null,   -- per-device monotonic counter, assigned on the tablet
  value             jsonb,
  client_updated_at timestamptz not null,
  received_at       timestamptz not null default now(),
  unique (form_id, field_id, device_id, seq)  -- makes retries harmless
);

create table field_current (
  form_id           uuid        not null,
  field_id          text        not null,
  value             jsonb,
  client_updated_at timestamptz not null,
  device_id         text        not null,
  seq               bigint      not null,
  primary key (form_id, field_id)
);
```

**Endpoint**

```ts
import express from "express";
import { z } from "zod";
import { Pool } from "pg";

const pool = new Pool();
const router = express.Router();

const FieldSubmission = z.object({
  formId: z.string().uuid(),
  fieldId: z.string().min(1).max(200),
  deviceId: z.string().min(1).max(200),
  seq: z.number().int().nonnegative(),
  value: z.unknown(),                       // string, number, array, null, etc.
  clientUpdatedAt: z.string().datetime(),   // when the inspector entered it
});
type FieldSubmission = z.infer<typeof FieldSubmission>;

async function saveField(client: import("pg").PoolClient, f: FieldSubmission) {
  const inserted = await client.query(
    `insert into field_events
       (form_id, field_id, device_id, seq, value, client_updated_at)
     values ($1,$2,$3,$4,$5,$6)
     on conflict (form_id, field_id, device_id, seq) do nothing
     returning id`,
    [f.formId, f.fieldId, f.deviceId, f.seq, JSON.stringify(f.value ?? null), f.clientUpdatedAt]
  );

  if (inserted.rowCount === 0) return { duplicate: true };

  // Latest client timestamp wins; older late-arriving edits don't clobber newer ones,
  // but they remain in field_events.
  await client.query(
    `insert into field_current
       (form_id, field_id, value, client_updated_at, device_id, seq)
     values ($1,$2,$3,$4,$5,$6)
     on conflict (form_id, field_id) do update
       set value = excluded.value,
           client_updated_at = excluded.client_updated_at,
           device_id = excluded.device_id,
           seq = excluded.seq
     where excluded.client_updated_at >= field_current.client_updated_at`,
    [f.formId, f.fieldId, JSON.stringify(f.value ?? null), f.clientUpdatedAt, f.deviceId, f.seq]
  );
  return { duplicate: false };
}

// Single field
router.post("/api/fields", express.json({ limit: "256kb" }), async (req, res) => {
  const parsed = FieldSubmission.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });

  const client = await pool.connect();
  try {
    await client.query("begin");
    const result = await saveField(client, parsed.data);
    await client.query("commit");
    // 200 for both new and duplicate: the client should treat either as "safely stored"
    return res.status(200).json({ ok: true, ...result });
  } catch (err) {
    await client.query("rollback").catch(() => {});
    console.error(err);
    return res.status(500).json({ ok: false }); // client keeps it in the outbox and retries
  } finally {
    client.release();
  }
});

// Batch, for flushing the outbox when signal returns
router.post("/api/fields/batch", express.json({ limit: "5mb" }), async (req, res) => {
  const parsed = z.array(FieldSubmission).max(500).safeParse(req.body?.fields);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.flatten() });

  const client = await pool.connect();
  try {
    await client.query("begin");
    const ordered = [...parsed.data].sort((a, b) => a.seq - b.seq);
    for (const f of ordered) await saveField(client, f);
    await client.query("commit");
    return res.status(200).json({
      ok: true,
      acked: parsed.data.map(f => ({ formId: f.formId, fieldId: f.fieldId, deviceId: f.deviceId, seq: f.seq })),
    });
  } catch (err) {
    await client.query("rollback").catch(() => {});
    console.error(err);
    return res.status(500).json({ ok: false });
  } finally {
    client.release();
  }
});

export default router;
```

**Design notes**
- **Ack only after commit.** A 2xx means the data is durable, so the tablet can safely delete it from the outbox. Anything else means keep it and retry with backoff.
- **Client-generated `deviceId` + `seq`** is the idempotency key. Retrying the same field 10 times produces one row.
- **Append-only `field_events`** means nothing is overwritten or lost, even with conflicting edits from two devices. You can audit or resolve conflicts later.
- **Clock skew:** "latest wins" relies on tablet clocks, which can be wrong. If that matters, switch the comparison to `(device_id, seq)` within a device, or flag cross-device conflicts for review rather than auto-resolving.
- **Not included:** authorization (checking that the user may write to this `formId`), rate limiting, and attachments. Photos should use a separate resumable-upload path.

I can also sketch the client side: the IndexedDB outbox, retry/backoff, and a "pending sync" indicator so inspectors know what has reached the server before they leave a site.

