    req.session.userId = req.body.userId;
    (req.session as any).tenantId = req.body.tenantId;
    req.session.save(() => res.status(204).end());
  });

  await cleanup();
  for (const [tenantId, rows] of Object.entries(seed)) {
    for (const r of rows) {
      await db.query(
        "INSERT INTO orders (id, tenant_id, item) VALUES ($1, $2, $3)",
        [r.id, tenantId, r.item]
      );
    }
  }
});

afterAll(async () => {
  await cleanup();
  await db.end();
});

async function cleanup() {
  await db.query("DELETE FROM orders WHERE id LIKE 'iso-%'");
}

describe.each(EXPORT_ROUTES)("tenant isolation for %s", (route) => {
  const cases = [
    { me: TENANT_A, other: TENANT_B },
    { me: TENANT_B, other: TENANT_A },
  ];

  it.each(cases)("export for $me contains none of $other's rows", async ({ me, other }) => {
    const agent = await loginAs(me);
    const res = await agent.get(route).expect(200);

    const rows: Array<{ id: string; tenant_id: string }> = res.body;
    const body = JSON.stringify(res.body);

    // Guard against a vacuous pass: the export must actually contain our rows.
    const ownIds = seed[me].map((r) => r.id).sort();
    const returnedSeedIds = rows.filter((r) => r.id.startsWith("iso-")).map((r) => r.id).sort();
    expect(returnedSeedIds).toEqual(ownIds);

    // No row belongs to another tenant.
    expect(rows.every((r) => r.tenant_id === me)).toBe(true);

    // No trace of the other tenant's data anywhere in the payload.
    for (const r of seed[other]) {
      expect(body).not.toContain(r.id);
      expect(body).not.toContain(r.item);
    }
  });

  it("ignores a tenant id supplied by the client", async () => {
    const agent = await loginAs(TENANT_A);
    const res = await agent
      .get(route)
      .query({ tenantId: TENANT_B, tenant_id: TENANT_B })
      .set("X-Tenant-Id", TENANT_B)
      .expect(200);

    const body = JSON.stringify(res.body);
    for (const r of seed[TENANT_B]) {
      expect(body).not.toContain(r.id);
    }
  });

  it("rejects unauthenticated requests", async () => {
    await request(app).get(route).expect(403);
  });

  it("rejects a session with no tenant id", async () => {
    const agent = request.agent(app);
    await agent.post("/__test/login").send({ userId: "orphan-user" }).expect(204);
    await agent.get(route).expect(403);
  });
});
```

Some notes on the design:

- **The non-empty check matters.** If seeding silently fails, "no rows from tenant B" passes trivially. Comparing the returned seed ids to the expected ones rules that out.
- **It searches the serialized payload**, not just `tenant_id`. If an export later joins another table, another tenant's data could leak through a column that has no `tenant_id`.
- **The spoofing test** covers query params and a header, the usual places a "helpful" fallback sneaks in.
- **It runs in both directions**, so a bug that only affects one tenant still shows up.
- **`EXPORT_ROUTES` is the weak point.** A new export endpoint that isn't listed is untested. To close that gap, add a test that walks `app._router.stack` and fails if any `/exports/*` route is missing from the list.

Before trusting the test, prove it can fail. Temporarily remove the `WHERE tenant_id = $1` from one export query and confirm the cross-tenant cases go red.

Point `DATABASE_URL` at a dedicated test database. The cleanup only deletes `iso-` rows, but the test still shouldn't run against shared or production data.

