```js
// avatarUpload.js
const express = require("express");
const multer = require("multer");

const MAX_BYTES = 5 * 1024 * 1024; // 5 MB
const MULTIPART_OVERHEAD = 64 * 1024; // boundaries/headers slack for the early check

const upload = multer({
  storage: multer.memoryStorage(), // fine at 5 MB cap; avoids temp files
  limits: {
    fileSize: MAX_BYTES, // enforced while streaming, so oversized uploads are cut off
    files: 1,
    fields: 0,
  },
});

// Identify the real type from magic bytes, not the client-supplied Content-Type.
function sniffImageType(buf) {
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) {
    return "image/jpeg";
  }
  const pngSig = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  if (buf.length >= 8 && pngSig.every((b, i) => buf[i] === b)) {
    return "image/png";
  }
  return null;
}

// Cheap early rejection when the client declares a too-large body.
// Not sufficient on its own (header can be absent or wrong); multer's limit is the real guard.
function rejectOversizedByHeader(req, res, next) {
  const declared = Number(req.headers["content-length"]);
  if (Number.isFinite(declared) && declared > MAX_BYTES + MULTIPART_OVERHEAD) {
    return res.status(413).json({ error: "File too large. Maximum size is 5 MB." });
  }
  next();
}

const router = express.Router();

router.post(
  "/users/me/avatar",
  /* requireAuth, */ // plug in your auth middleware here
  rejectOversizedByHeader,
  upload.single("avatar"),
  async (req, res) => {
    if (!req.file) {
      return res.status(400).json({ error: "No file provided (field name: 'avatar')." });
    }

    const type = sniffImageType(req.file.buffer);
    if (!type) {
      return res.status(415).json({ error: "Only JPEG and PNG images are accepted." });
    }

    // TODO next steps:
    //   1. resize to 256px (e.g. sharp) and re-encode
    //   2. upload to object storage
    //   3. save the resulting key/URL on the user record

    return res.status(202).json({ message: "Upload accepted", contentType: type });
  }
);

// Translate multer errors into proper HTTP responses.
router.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === "LIMIT_FILE_SIZE") {
      return res.status(413).json({ error: "File too large. Maximum size is 5 MB." });
    }
    return res.status(400).json({ error: `Upload error: ${err.code}` });
  }
  next(err);
});

module.exports = router;
```

A few notes on the choices:

- **Two layers of size checking.** The `Content-Length` check rejects honest oversized uploads immediately. Clients can omit or falsify that header, so multer's `fileSize` limit is the real enforcement: it counts bytes as they stream in and aborts at 5 MB.
- **Magic-byte sniffing.** The `Content-Type` and filename come from the client, so I check the file signature instead. The resize step will fully decode the image, which is the real validity check. Make sure it fails cleanly on corrupt files (return a 400, not a 500).
- **Re-encoding on resize** also strips EXIF metadata such as GPS location, which you'll want for profile pictures. With `sharp`, that's the default unless you call `.withMetadata()`.
- **Rate limiting.** Consider a per-user limit on this endpoint, since each request can cost up to 5 MB of memory.

