I've assumed S3-compatible storage with the AWS SDK v3. This also works for R2, MinIO, and similar services if you set an endpoint. If you use GCS or something else, tell me and I'll port it.

```js
// avatarStorage.js
const crypto = require("crypto");
const sharp = require("sharp");
const { S3Client, PutObjectCommand, DeleteObjectCommand } = require("@aws-sdk/client-s3");

const AVATAR_SIZE = 256;
const BUCKET = process.env.AVATAR_BUCKET;
const PUBLIC_BASE_URL = process.env.AVATAR_PUBLIC_BASE_URL; // CDN or public bucket URL, no trailing slash

const s3 = new S3Client({
  region: process.env.S3_REGION || "auto",
  endpoint: process.env.S3_ENDPOINT, // leave unset for AWS S3
});

class InvalidImageError extends Error {}

async function processAvatar(inputBuffer) {
  try {
    return await sharp(inputBuffer, { limitInputPixels: 40_000_000 }) // guards against decompression bombs
      .rotate() // apply EXIF orientation *before* metadata is stripped
      .resize(AVATAR_SIZE, AVATAR_SIZE, { fit: "cover" }) // square center crop
      .webp({ quality: 85 }) // keeps PNG transparency; metadata is dropped by default
      .toBuffer();
  } catch (err) {
    throw new InvalidImageError("Could not decode image");
  }
}

/**
 * Resizes and stores an avatar. Returns { key, url }.
 * Throws InvalidImageError if the file can't be decoded.
 */
async function storeAvatar(userId, inputBuffer) {
  const body = await processAvatar(inputBuffer);

  // Unique key per upload, so the URL changes when the avatar does
  // and CDNs/browsers can cache each version forever.
  const key = `avatars/${userId}/${crypto.randomUUID()}.webp`;

  await s3.send(
    new PutObjectCommand({
      Bucket: BUCKET,
      Key: key,
      Body: body,
      ContentType: "image/webp",
      CacheControl: "public, max-age=31536000, immutable",
    })
  );

  return { key, url: `${PUBLIC_BASE_URL}/${key}` };
}

async function deleteAvatar(key) {
  await s3.send(new DeleteObjectCommand({ Bucket: BUCKET, Key: key }));
}

module.exports = { storeAvatar, deleteAvatar, InvalidImageError };
```

