I don't know your stack, so I wrote this in Python with `requests`. It's easy to port if you're on something else.

```python
import logging
import os
import time

import requests

logger = logging.getLogger(__name__)


class SlackWebhookError(Exception):
    """Raised when a Slack webhook post fails permanently."""


def _escape(text: str) -> str:
    # Slack requires these three characters to be escaped in mrkdwn text.
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


class SlackWebhookClient:
    def __init__(
        self,
        webhook_url: str | None = None,
        *,
        timeout: float = 5.0,
        max_retries: int = 3,
        session: requests.Session | None = None,
    ):
        self.webhook_url = webhook_url or os.environ["SLACK_WEBHOOK_URL"]
        self.timeout = timeout
        self.max_retries = max_retries
        self.session = session or requests.Session()

    def send(self, text: str, blocks: list[dict] | None = None) -> None:
        """Post a message. `text` is the fallback shown in notifications."""
        payload: dict = {"text": text}
        if blocks:
            payload["blocks"] = blocks

        for attempt in range(self.max_retries + 1):
            try:
                resp = self.session.post(
                    self.webhook_url, json=payload, timeout=self.timeout
                )
            except (requests.Timeout, requests.ConnectionError) as exc:
                if attempt == self.max_retries:
                    raise SlackWebhookError(f"Slack unreachable: {exc}") from exc
                time.sleep(self._backoff(attempt))
                continue

            if resp.status_code == 200:
                return

            retryable = resp.status_code == 429 or resp.status_code >= 500
            if not retryable or attempt == self.max_retries:
                # Slack puts a short reason in the body, e.g. "invalid_payload",
                # "channel_not_found", "channel_is_archived", "no_service".
                raise SlackWebhookError(
                    f"Slack returned {resp.status_code}: {resp.text[:200]}"
                )

            retry_after = resp.headers.get("Retry-After")
            delay = float(retry_after) if retry_after else self._backoff(attempt)
            time.sleep(delay)

    @staticmethod
    def _backoff(attempt: int) -> float:
        return min(2 ** attempt, 10)

    def send_ticket_alert(
        self,
        *,
        ticket_id: str,
        title: str,
        priority: str,
        url: str,
        requester: str | None = None,
    ) -> None:
        title = _escape(title)[:150]
        fallback = f"New {priority} priority ticket #{ticket_id}: {title}"

        fields = [
            {"type": "mrkdwn", "text": f"*Priority:*\n{_escape(priority)}"},
            {"type": "mrkdwn", "text": f"*Ticket:*\n#{_escape(ticket_id)}"},
        ]
        if requester:
            fields.append(
                {"type": "mrkdwn", "text": f"*Requester:*\n{_escape(requester)}"}
            )

        blocks = [
            {
                "type": "section",
                "text": {
                    "type": "mrkdwn",
                    "text": f":rotating_light: *New high-priority ticket*\n<{url}|{title}>",
                },
            },
            {"type": "section", "fields": fields},
        ]
        self.send(fallback, blocks)
```

Example use in the ticket-created handler:

```python
