## `scripts/extract-strings.js`

```js
#!/usr/bin/env node
/**
 * Extracts user-facing strings from JSX/TSX into a flat message file.
 *
 * Usage: node scripts/extract-strings.js
 * Output:
 *   src/locales/en.json      - key -> English string (existing keys are preserved)
 *   src/locales/review.json  - strings that need a human look before translating
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { globSync } = require('glob');
const parser = require('@babel/parser');
const traverse = require('@babel/traverse').default;

const SRC_GLOB = 'src/**/*.{js,jsx,ts,tsx}';
const IGNORE = ['**/*.test.*', '**/*.spec.*', '**/*.stories.*', 'src/locales/**'];
const OUT_DIR = 'src/locales';
const TRANSLATABLE_ATTRS = new Set([
  'placeholder', 'title', 'alt', 'label', 'aria-label', 'aria-description',
]);

const messages = {};  // key -> text
const review = [];    // { file, line, text, reason }

const normalize = (s) => s.replace(/\s+/g, ' ').trim();
const hasLetters = (s) => /\p{L}/u.test(s);

function namespaceFor(file) {
  const base = path.basename(file).replace(/\.[^.]+$/, '');
  return base.replace(/[-_.](\w)/g, (_, c) => c.toUpperCase())
             .replace(/^\w/, (c) => c.toLowerCase());
}

function slugify(text) {
  const words = text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .split(' ')
    .filter(Boolean)
    .slice(0, 5);
  return words
    .map((w, i) => (i === 0 ? w : w[0].toUpperCase() + w.slice(1)))
    .join('')
    .slice(0, 40) || 'text';
}

function keyFor(file, text) {
  const ns = namespaceFor(file);
  let key = `${ns}.${slugify(text)}`;
  if (messages[key] !== undefined && messages[key] !== text) {
    const hash = crypto.createHash('sha1').update(text).digest('hex').slice(0, 4);
    key = `${key}_${hash}`;
  }
  return key;
}

function add(file, text) {
  const key = keyFor(file, text);
  messages[key] = text;
  return key;
}

function extractFile(file) {
  const code = fs.readFileSync(file, 'utf8');
  let ast;
  try {
    ast = parser.parse(code, {
      sourceType: 'module',
      plugins: ['jsx', 'typescript'],
    });
  } catch (e) {
    review.push({ file, line: 0, text: '', reason: `Parse error: ${e.message}` });
    return;
  }

  traverse(ast, {
    JSXText(p) {
      const text = normalize(p.node.value);
      if (!text || !hasLetters(text)) return;

      // Text mixed with {expressions} usually means a sentence is split into
      // fragments, which can't be translated correctly (word order differs in Spanish).
      const siblings = p.parent.children || [];
      const hasExpr = siblings.some(
        (c) => c.type === 'JSXExpressionContainer' || c.type === 'JSXElement'
      );
      if (hasExpr) {
        review.push({
          file,
          line: p.node.loc.start.line,
          text,
          reason: 'Text fragment next to an expression/element; likely needs interpolation or rich-text formatting',
        });
      }
      add(file, text);
    },

    JSXAttribute(p) {
      const name = p.node.name.name;
      if (!TRANSLATABLE_ATTRS.has(name)) return;
      const v = p.node.value;
      if (v && v.type === 'StringLiteral') {
        const text = normalize(v.value);
        if (text && hasLetters(text)) add(file, text);
      }
    },
  });
}

function main() {
  const outFile = path.join(OUT_DIR, 'en.json');
  const existing = fs.existsSync(outFile)
    ? JSON.parse(fs.readFileSync(outFile, 'utf8'))
    : {};

  const files = globSync(SRC_GLOB, { ignore: IGNORE });
  files.forEach(extractFile);

  // Existing keys win, so hand-edited strings aren't overwritten on re-run.
  const merged = { ...messages, ...existing };
  const sorted = Object.fromEntries(
    Object.entries(merged).sort(([a], [b]) => a.localeCompare(b))
  );

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(outFile, JSON.stringify(sorted, null, 2) + '\n');
  fs.writeFileSync(
    path.join(OUT_DIR, 'review.json'),
    JSON.stringify(review, null, 2) + '\n'
  );

  console.log(`Scanned ${files.length} files`);
  console.log(`Wrote ${Object.keys(sorted).length} messages to ${outFile}`);
  console.log(`${review.length} items flagged in ${OUT_DIR}/review.json`);
}

main();
```

## What it doesn't catch

- **Strings in plain JS**, such as toasts, error messages, validation text, and `document.title`. These need `t()` calls and a different detection approach.
- **Template literals and concatenation** like `` `Hello ${name}` ``. These need to become ICU or interpolated messages (`"Hello {name}"`) by hand.
- **Plurals** like `"1 item"` / `"2 items"`. Spanish follows different plural rules, so use your library's plural syntax.
- **Fragments around expressions or links**, e.g. `Click <a>here</a> to continue`. The script extracts these but flags them in `review.json`, since they should be one message with rich-text placeholders.

It also doesn't rewrite your components to call `t('key')`. That's a separate codemod, and I can write it once the extraction output looks right.

