## `src/i18n/config.js`

```js
export const SUPPORTED = [
  { code: 'en', name: 'English' },
  { code: 'es', name: 'Español' },
];
export const DEFAULT_LOCALE = 'en';
const STORAGE_KEY = 'app.locale';

// 'es-MX' -> 'es'. Returns null if we don't support the language.
export function resolveLocale(candidate) {
  if (!candidate) return null;
  const base = candidate.toLowerCase().split('-')[0];
  return SUPPORTED.find((l) => l.code === base)?.code ?? null;
}

export function detectInitialLocale() {
  try {
    const saved = resolveLocale(localStorage.getItem(STORAGE_KEY));
    if (saved) return saved;
  } catch {} // storage can be blocked (private mode, etc.)

  for (const tag of navigator.languages ?? [navigator.language]) {
    const match = resolveLocale(tag);
    if (match) return match;
  }
  return DEFAULT_LOCALE;
}

export function persistLocale(code) {
  try { localStorage.setItem(STORAGE_KEY, code); } catch {}
}
```

## `src/i18n/LocaleProvider.jsx`

```jsx
import { createContext, useCallback, useContext, useEffect, useState } from 'react';
import en from '../locales/en.json'; // bundled: always available as a fallback
import { DEFAULT_LOCALE, detectInitialLocale, persistLocale, resolveLocale } from './config';

const LocaleContext = createContext(null);

export function LocaleProvider({ children }) {
  const [requested, setRequested] = useState(detectInitialLocale);
  // locale and messages are stored together so they never get out of sync
  const [active, setActive] = useState({ locale: DEFAULT_LOCALE, messages: en });

  useEffect(() => {
    let cancelled = false;

    const apply = (messages) => {
      if (cancelled) return;
      // Spread English underneath so untranslated keys fall back to English
      // instead of rendering as raw keys.
      setActive({ locale: requested, messages: { ...en, ...messages } });
      document.documentElement.lang = requested;
    };

    if (requested === DEFAULT_LOCALE) apply({});
    else {
      import(`../locales/${requested}.json`)
        .then((m) => apply(m.default))
        .catch((err) => {
          console.error(`Failed to load locale "${requested}"`, err);
          apply({});
        });
    }
    return () => { cancelled = true; };
  }, [requested]);

  const setLocale = useCallback((code) => {
    const resolved = resolveLocale(code);
    if (!resolved) return;
    persistLocale(resolved);
    setRequested(resolved);
  }, []);

  return (
    <LocaleContext.Provider value={{ locale: active.locale, messages: active.messages, setLocale }}>
      {/* Plug in your i18n library here, e.g.
          <IntlProvider locale={active.locale} messages={active.messages}>{children}</IntlProvider> */}
      {children}
    </LocaleContext.Provider>
  );
}

export function useLocale() {
  const ctx = useContext(LocaleContext);
  if (!ctx) throw new Error('useLocale must be used inside <LocaleProvider>');
  return ctx;
}
```

