export function LanguageSwitcher({ label = 'Language' }) {
  const { locale, setLocale } = useLocale();

  return (
    <select aria-label={label} value={locale} onChange={(e) => setLocale(e.target.value)}>
      {SUPPORTED.map(({ code, name }) => (
