**`render_report.py`**
```python
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal

from jinja2 import Environment, FileSystemLoader, select_autoescape
from weasyprint import HTML

env = Environment(
    loader=FileSystemLoader("templates"),
    autoescape=select_autoescape(["html"]),
)

def _num(v):
    v = Decimal(v)
    return f"{v:,.0f}" if v == v.to_integral_value() else f"{v:,.2f}"

env.filters["num"] = _num

METRIC_LABELS = {          # map raw metric keys to display names
    "api_calls": "API calls",
    "storage_gb": "Storage (GB)",
    "seats": "Seats",
}

def _change(pct):
    if pct is None:
        return "—", "na"
    if pct > 0:
        return f"▲ {pct:.1f}%", "up"
    if pct < 0:
        return f"▼ {abs(pct):.1f}%", "down"
    return "0.0%", "flat"

def _line_chart_svg(values, width=640, height=110, pad=6):
    vals = [float(v) for v in values]
    hi = max(vals) or 1.0
    step = (width - 2 * pad) / max(len(vals) - 1, 1)
    pts = [
        (pad + i * step, height - pad - (v / hi) * (height - 2 * pad))
        for i, v in enumerate(vals)
    ]
    line = " ".join(f"{x:.1f},{y:.1f}" for x, y in pts)
    area = f"{pad},{height - pad} {line} {pts[-1][0]:.1f},{height - pad}"
    return (
        f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg">'
        f'<polygon points="{area}" fill="#e8f0fe"/>'
        f'<polyline points="{line}" fill="none" stroke="#1a56db" stroke-width="1.5"/>'
        f'<text x="{width - pad}" y="12" text-anchor="end" font-size="9" fill="#888">'
        f'peak {hi:,.0f}</text>'
        f'</svg>'
    )

def build_context(customer, month_start: date, totals_rows, daily_rows):
    # totals_rows: rows from the totals query (metric, current_total, previous_total, pct_change)
    metrics = []
    for r in totals_rows:
        text, cls = _change(r["pct_change"])
        metrics.append({
            "label": METRIC_LABELS.get(r["metric"], r["metric"]),
            "current_total": r["current_total"],
            "previous_total": r["previous_total"],
            "change_text": text,
            "change_class": cls,
        })

    # daily_rows: rows from the daily query (day, metric, total).
    # Zero-fill so every metric has a value for every day of the month.
    next_month = (month_start.replace(day=28) + timedelta(days=4)).replace(day=1)
    days = [month_start + timedelta(days=i) for i in range((next_month - month_start).days)]
    by_metric = defaultdict(dict)
    for r in daily_rows:
        if r["metric"] is not None:           # skip the NULL-metric rows from empty days
            by_metric[r["metric"]][r["day"]] = r["total"]

    charts = [
        {
            "label": METRIC_LABELS.get(metric, metric),
            "svg": _line_chart_svg([series.get(d, 0) for d in days]),
        }
        for metric, series in sorted(by_metric.items())
    ]

    return {
        "customer": customer,
        "period_label": month_start.strftime("%B %Y"),
        "generated_at": date.today().isoformat(),
        "metrics": metrics,
        "charts": charts,
    }

def render_pdf(context) -> bytes:
    html = env.get_template("usage_summary.html").render(**context)
    return HTML(string=html).write_pdf()
```

**Notes**
- **Daily query fix:** my earlier daily query returns a `NULL` metric row for days with no events and omits metric/day combinations with no data. The `build_context` code above handles both by skipping `NULL` rows and zero-filling. You could also fix it in SQL by cross-joining the days with the customer's distinct metrics.
- **Charts:** I used hand-built inline SVG to avoid a matplotlib dependency. It draws one small chart per metric, since metrics like API calls and seats have very different scales. If you want axes, labels, or multiple series, swap in matplotlib and embed the SVG output.
- **Gauge metrics:** the template labels everything as "total." If you use `MAX` or end-of-month values for seats or storage, add a per-metric "aggregation" label so the column header isn't misleading.
- **Fonts:** WeasyPrint uses system fonts. In a container, install the fonts you want (e.g. `fonts-liberation`) or the PDF will fall back to something ugly.
- **Zero-usage customers:** the template shows a "No usage recorded" row. You may want the job to skip them or still send the report, depending on what account managers expect.
- **Sample data:** render with fake `totals_rows` and `daily_rows` while iterating on the design, so you don't need the database to tweak the layout.

